describe('errorMessage per kind', () => {
  it('says something specific and human for every kind', () => {
    expect(errorMessage(new AppError('network', 'x'))).toMatch(/connection/i);
    expect(errorMessage(new AppError('auth', 'x', { status: 401 }))).toMatch(/sign in/i);
    expect(errorMessage(new AppError('notFound', 'x', { status: 404 }))).toMatch(/found/i);
    expect(errorMessage(new AppError('server', 'x', { status: 500 }))).toMatch(/our side/i);
    expect(errorMessage(new AppError('validation', 'Bad postcode'))).toBe('Bad postcode');
    expect(errorMessage(new AppError('validation', ''))).toMatch(/check your input/i);
    expect(errorMessage(new AppError('unknown', ''))).toMatch(/went wrong/i);
  });
  it('prefers the message the API itself sent, except on a network failure', () => {
    expect(errorMessage(new AppError('server', 'generic', { apiMessage: 'Card declined' }))).toBe('Card declined');
    expect(errorMessage(new AppError('network', 'generic', { apiMessage: 'Card declined' }))).toMatch(/connection/i);
  });
});

describe('pickMessage on a raw body', () => {
  it('parses a JSON string body before looking inside it', () => {
    expect(pickMessage(JSON.stringify({ message: 'from json' }))).toBe('from json');
  });
  it('returns a long plain-text body truncated rather than whole', () => {
    const long = 'x'.repeat(1000);
    const out = pickMessage(long);
    expect(out).toBeDefined();
    expect(out!.length).toBeLessThanOrEqual(300);
  });
  it('gives up on shapes that carry no message', () => {
    expect(pickMessage({ nothing: true })).toBeUndefined();
    expect(pickMessage([])).toBeUndefined();
    expect(responseMessage({})).toBeTruthy();
  });
});

describe('parseErrorBody', () => {
  it('parses a JSON body string, and keeps an unparseable one as text', () => {
    const parsed = parseErrorBody(new AppError('server', 'x', { cause: { body: '{"detail":"y"}' } }));
    expect(parsed).toEqual({ detail: 'y' });
    expect(parseErrorBody(new AppError('server', 'x', { cause: { body: 'not json' } }))).toBe('not json');
  });
  it('falls back to the message when there is no body at all', () => {
    expect(parseErrorBody(new AppError('server', 'the message'))).toBe('the message');
  });
});

