describe('firstMatchingRule', () => {
  it('matches on the HTTP status when the rule says status', () => {
    const rules: ResponseRule[] = [{ source: 'status', op: 'gte', value: 400, navigateTo: 'Failure' }];
    expect(firstMatchingRule(rules, {}, 500)?.navigateTo).toBe('Failure');
    expect(firstMatchingRule(rules, {}, 200)).toBeNull();
  });
  it('looks inside a { data } envelope when the plain path finds nothing', () => {
    const rules: ResponseRule[] = [{ source: 'body', op: 'eq', path: 'code', value: 'OK', navigateTo: 'Home' }];
    expect(firstMatchingRule(rules, { code: 'OK' }, 200)?.navigateTo).toBe('Home');
    // the same rule must still fire when the API wraps its payload
    expect(firstMatchingRule(rules, { data: { code: 'OK' } }, 200)?.navigateTo).toBe('Home');
  });
});

describe('fmt number grouping', () => {
  it('groups in threes by default', () => {
    expect(fmt('1234567', [['group']])).toBe('1,234,567');
  });
  it('groups the Indian way — last three, then pairs', () => {
    expect(fmt('1234567', [['group', 'indian']])).toBe('12,34,567');
    expect(fmt('567', [['group', 'indian']])).toBe('567');
  });
  it('uses the separators each named style expects', () => {
    expect(fmt('1234.5', [['group', 'dot']])).toBe('1.234,5');
    expect(fmt('1234.5', [['group', 'space']])).toBe('1 234.5');
  });
  it('keeps a negative sign and leaves non-numeric text alone', () => {
    expect(fmt('-1234', [['group']])).toBe('-1,234');
    expect(fmt('not a number', [['group']])).toBe('not a number');
  });
});

describe('useFieldScroll', () => {
  it('tracks the scroll offset and focuses the first field in error', () => {
    let handle: ReturnType<typeof useFieldScroll> | null = null;
    const Probe = () => { handle = useFieldScroll(); return <Text>probe</Text>; };
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(<Probe />); });
    const focus = jest.fn();
    const scrollTo = jest.fn();
    // a scroll container and a field node, shaped as RN hands them over
    handle!.scrollProps.ref({ scrollTo, measureLayout: undefined });
    handle!.scrollProps.onScroll({ nativeEvent: { contentOffset: { y: 120 } } } as never);
    handle!.scrollProps.onScroll({} as never); // a malformed event must not throw
    handle!.bind('field-1')({
      focus,
      measureLayout: (_n: unknown, cb: (x: number, y: number) => void) => cb(0, 240),
      measureInWindow: (cb: (x: number, y: number) => void) => cb(0, 240),
    });
    focusFirstError(['field-1'], { 'field-1': 'Required' });
    expect(focus).toHaveBeenCalled();
    // unbinding removes it, so a later error cannot focus a gone node
    handle!.bind('field-1')(null);
    focusFirstError(['field-1'], { 'field-1': 'Required' });
    act(() => tree.unmount());
  });
  it('does nothing when no listed field has an error', () => {
    expect(() => focusFirstError(['a', 'b'], {})).not.toThrow();
  });
});

describe('I18nProvider locale change', () => {
  it('switches i18next and reports whether the direction flipped', async () => {
    let ctx: ReturnType<typeof useI18n> | null = null;
    const Probe = () => { ctx = useI18n(); return <Text>{ctx.locale}</Text>; };
    let tree!: renderer.ReactTestRenderer;
    await act(async () => { tree = renderer.create(<I18nProvider><Probe /></I18nProvider>); });
    const start = ctx!.locale;
    for (const l of LOCALES) {
      // eslint-disable-next-line no-await-in-loop
      let flipped = false;
      // eslint-disable-next-line no-await-in-loop
      await act(async () => { flipped = await ctx!.setLocale(l); });
      // A locale that changes layout DIRECTION reports true and the app
      // relaunches — I18nManager.forceRTL only takes effect on a fresh start —
      // so the in-place state deliberately does NOT move for those.
      expect(typeof flipped).toBe('boolean');
      if (!flipped) expect(ctx!.locale).toBe(l);
      expect(ctx!.t('any.key')).toBeTruthy();
    }
    await act(async () => { await ctx!.setLocale(start); });
    await act(async () => tree.unmount());
  });
});
